echo "host=$(hostname) up=$(uptime -s)"; echo "-- who"; who
echo "-- puertos escuchando (no loopback)"; ss -Hltnu | awk '{print $1, $5}' | grep -vE ' (127\.|\[::1\]|\[::ffff:127)' | sort -u
echo "-- conexiones TCP/UDP fuera del aula"; ss -Htun state established 2>/dev/null | awk '{print $1, $5, $6}' | grep -vE ' (127\.|10\.100\.41\.|\[::1\]|\[::ffff:127|\[::ffff:10\.100\.41)' | head
echo "-- procesos de usuarios humanos (no utec_alumno/sistema)"; ps -eo user:20,etime,args --no-headers | awk '$1!="root" && $1!="utec_alumno" && $1!~/^(systemd|message|syslog|avahi|polkit|rtkit|colord|kernoops|gdm|whoopsie|gnome-r|geoclue|cups|dnsmasq|nobody|_rpc|usbmux|fwupd|sssd|tss|pipewire|dbus|uuidd|_flatpak|nvidia)/' | head
echo "-- herramientas remotas / tuneles"; ps -eo user,etime,args --no-headers | grep -iE 'code-tunnel|code tunnel|vscode-server|cloudflared|ngrok|frpc|tailscale|zerotier|anydesk|rustdesk|teamviewer|x11vnc|vnc|xrdp|ssh -R|ssh -f|autossh|bore |localtunnel|tmate|wstunnel|chisel' | grep -v grep | head
ls -d /home/*/.vscode-server /home/*/.vscode/cli /root/.vscode-server 2>/dev/null
echo "-- llaves SSH autorizadas"; for h in /home/* /root; do [ -s $h/.ssh/authorized_keys ] && echo "$h: $(wc -l < $h/.ssh/authorized_keys) llave(s): $(awk '{print $NF}' $h/.ssh/authorized_keys | tr '\n' ' ')"; done 2>/dev/null
echo "-- cron"; crontab -l 2>/dev/null | grep -v '^#'; ls /etc/cron.d/ 2>/dev/null | tr '\n' ' '; echo
echo "-- servicios habilitados no estándar"; systemctl list-unit-files --state=enabled --no-legend --type=service | awk '{print $1}' | grep -vE '^(accounts-daemon|acpid|anacron|apparmor|apport|avahi|blk|bluetooth|console-setup|cron|cups|dbus|dmesg|e2scrub|finalrd|fwupd|gdm|getty|gpu-manager|grub|irqbalance|kerneloops|keyboard|lvm|ModemManager|networkd|NetworkManager|nvidia|open-iscsi|open-vm|openvpn|pollinate|power-profiles|rsyslog|secureboot|setvtrgb|snapd|ssh|switcheroo|sysstat|systemd|thermald|ua-|ubuntu|udisks|ufw|unattended|wpa_supplicant|docker|containerd|lab-|nvidia|cloud|multipath|rsync|uuidd|whoopsie|spice|vgauth|dmesg|hibagent|gnome|sssd|tuned|bolt|colord|rtkit|kmod|plymouth|motd|apport|update|wsdd|ubuntu-advantage|pcscd|saned|alsa|brltty|casper|dbus|netplan|qemu|smartmontools|mdmonitor|thermal|cups-browsed|speech|switcheroo|rpc|nfs)'
echo "-- contenedores"; docker ps --format '{{.Names}} {{.Image}} {{.Ports}}' 2>&1 | head -5
